fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    let n = list.len();
    // k is 1-based and must satisfy 1 <= k < n
    assert!(n > 0 && k >= 1 && k < n, "k is out of allowed range");
    // We'll build a new Vec with capacity n-1
    let mut new_list = Vec::with_capacity(n - 1);
    // Take all elements before the k-th (1-based) element
    new_list.extend_from_slice(&list[..(k - 1)]);
    // Skip the k-th element and take the rest
    new_list.extend_from_slice(&list[k..]);
    new_list
}